// Author: MiYu. Native JASS syntax, bounded malformed input and archive source boundaries.
#include "jass.h"
#include <StormLib.h>
#include <functional>
#include <iostream>

using namespace war3;
using namespace war3::jass;
namespace {
void require(bool value,const char* message) {if(!value)throw std::runtime_error(message);}
template<class F> void rejects(F run) {try{run();}catch(const std::exception&){return;}throw std::runtime_error("Malformed JASS accepted");}
Program parse(std::string text) {return Program::parse({{"fixture.j",std::move(text),"authored test"}});}
void mpq(const fs::path& path,const std::vector<std::pair<std::string,std::string>>& files) {HANDLE archive=nullptr;require(SFileCreateArchive(path.c_str(),MPQ_CREATE_ARCHIVE_V1,32,&archive),"Cannot create script fixture archive");struct Close {HANDLE archive;~Close(){SFileCloseArchive(archive);}}close{archive};for(auto& [name,text]:files){HANDLE member=nullptr;require(SFileCreateFile(archive,name.c_str(),0,DWORD(text.size()),0,0,&member),"Cannot create script fixture member");bool write=SFileWriteFile(member,text.data(),DWORD(text.size()),0),finish=SFileFinishFile(member);require(write && finish,"Cannot write script fixture");}}
const char* entries="function config takes nothing returns nothing\nendfunction\nfunction main takes nothing returns nothing\nendfunction\n";
}
int wmain(int argc,wchar_t** argv) {
    if(argc!=2){std::cerr<<"Usage: war3_jass_tests <scratch-root>\n";return 2;}
    unsigned passed=0,failed=0;auto test=[&](const char* name,const std::function<void()>& run){try{run();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cout<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
    test("jass_declarations_and_source_positions",[]{auto p=parse("// comment\rtype myhandle extends handle\rconstant native Convert takes integer i returns myhandle\rglobals\rconstant integer A='hfoo'\rinteger array a\rreal r=.5\rstring text=\"function\"\rendglobals\rfunction Test takes integer i, real x returns nothing\rlocal integer y=1\rlocal integer array values\rendfunction\r");require(p.types().size()==1 && p.types()[0].parent=="handle" && p.functions()[0].native && p.functions()[0].constant,"Declaration kinds lost");require(p.globals().size()==4 && p.globals()[0].constant && p.globals()[1].array && p.expression(p.globals()[0].initializer).kind==ExpressionKind::Rawcode,"Global declarations lost");require(p.expression(p.globals()[3].initializer).kind==ExpressionKind::String && p.expression(p.globals()[3].initializer).text=="function","String interpreted as keyword");auto f=p.function("Test");require(f && f->parameters.size()==2 && f->locals.size()==2 && f->locals[1].array && f->position.line==10,"CR-only source locations differ");});
    test("jass_expression_precedence_and_references",[]{auto p=parse("function Calc takes nothing returns real\nreturn -1 + 2 * 3 / 4\nendfunction\nfunction Flag takes nothing returns boolean\nreturn not false and 1 < 2 or 3 == 4\nendfunction\nfunction Callback takes nothing returns code\nreturn function Calc\nendfunction\n");auto& sum=p.expression(p.statement(p.function("Calc")->body[0]).value);require(sum.text=="+" && p.expression(sum.operands[0]).kind==ExpressionKind::Unary && p.expression(sum.operands[1]).text=="/" && p.expression(p.expression(sum.operands[1]).operands[0]).text=="*","Arithmetic precedence or associativity differs");auto& flag=p.expression(p.statement(p.function("Flag")->body[0]).value);require(flag.text=="or" && p.expression(flag.operands[0]).text=="and","Boolean precedence differs");require(p.expression(p.statement(p.function("Callback")->body[0]).value).kind==ExpressionKind::Function,"Function reference lost");});
    test("jass_string_literals_are_not_grammar",[]{for(auto value:{"-","+","not","(",")","if","function","or","and","false"}){auto p=parse(std::string("globals\nstring x=\"")+value+"\"\nendglobals\n");auto& e=p.expression(p.globals()[0].initializer);require(e.kind==ExpressionKind::String && e.text==value,"String contents became JASS grammar");}});
    test("jass_numeric_keyword_boundary",[]{auto p=parse("function f takes real x returns nothing\nif x<=0.then\nreturn\nendif\nendfunction\n");auto& condition=p.expression(p.statement(p.function("f")->body[0]).branches[0].condition);require(condition.text=="<=" && p.expression(condition.operands[1]).kind==ExpressionKind::Real && p.expression(condition.operands[1]).text=="0." && p.expression(condition.operands[1]).realBits==0,"Adjacent then corrupted real literal");});
    test("jass_real_literals_compile_to_native_bits",[]{auto p=parse("globals\nreal a=.5\nreal b=2147483647.0\nendglobals\n");require(p.expression(p.globals()[0].initializer).realBits==0x3f000000 && p.expression(p.globals()[1].initializer).realBits==0x4effffff,"Real AST literals used host numeric conversion");rejects([]{parse("globals\nreal a=1.0e3\nendglobals\n");});});
    test("jass_flow_arrays_calls_and_debug",[]{auto p=parse("function main takes nothing returns nothing\nlocal integer i=0\nloop\nexitwhen i>=4\nif i==0 then\nset values[i]=Call(\"(\", 0x1f, $FF)\nelseif i==1 then\ndebug call Trace(function main)\nelse\nset i=i+1\nendif\nendloop\nreturn\nendfunction\n");auto& loop=p.statement(p.function("main")->body[0]);require(loop.kind==StatementKind::Loop && p.statement(loop.body[0]).kind==StatementKind::ExitWhen,"Loop or exitwhen lost");auto& branch=p.statement(loop.body[1]);require(branch.kind==StatementKind::If && branch.branches.size()==3 && branch.branches[2].condition==none,"Conditional branches lost");auto& set=p.statement(branch.branches[0].statements[0]);require(set.index!=none && set.variable=="values" && p.expression(set.value).operands.size()==3,"Array assignment or arguments lost");require(p.statement(branch.branches[1].statements[0]).debug,"Debug statement flag lost");});
    test("jass_duplicate_names_and_case",[]{auto p=parse("globals\ninteger x\ninteger X\nendglobals\nfunction foo takes nothing returns nothing\nendfunction\nfunction Foo takes nothing returns nothing\nendfunction\n");require(p.globals().size()==2 && p.function("foo") && p.function("Foo"),"JASS names became case-insensitive");for(auto text:{"globals\ninteger x\ninteger x\nendglobals\n","function f takes integer x, integer x returns nothing\nendfunction\n","function f takes integer x returns nothing\nlocal real x\nendfunction\n","type T extends handle\ntype T extends handle\n","function f takes nothing returns nothing\nendfunction\nfunction f takes nothing returns nothing\nendfunction\n"})rejects([&]{parse(text);});});
    test("jass_malformed_lines_and_nesting",[]{for(auto text:{"globals\ninteger array a=2\nendglobals\n","globals\ninteger x=$\nendglobals\n","globals\ninteger x=1.2.3\nendglobals\n","globals\nstring x=\"bad\nendglobals\n","function f takes nothing returns nothing\nexitwhen true\nendfunction\n","function f takes nothing returns nothing\nif true then\nendfunction\n","function f takes nothing returns nothing\ncall 2\nendfunction\n","function f takes nothing returns nothing\nset x=1 local integer y\nendfunction\n"})rejects([&]{parse(text);});std::string text="function f takes nothing returns integer\nreturn ";text+=std::string(140,'(')+"1"+std::string(140,')')+"\nendfunction\n";rejects([&]{parse(text);});std::vector<Source> sources(33);rejects([&]{Program::parse(sources);});try{parse("\r\nfunction f takes nothing returns nothing\r\nset x=@\r\nendfunction\r\n");throw std::runtime_error("Expected diagnostic");}catch(const std::runtime_error& e){require(std::string(e.what()).starts_with("fixture.j:3:"),"Diagnostic lacks source/line");}});
    test("jass_common_scope_and_map_script_aliases",[&]{auto scratch=fs::absolute(argv[1])/(std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));fs::create_directories(scratch);mpq(scratch/L"war3.mpq",{{"Scripts\\common.j","type sourcehandle extends handle\n"},{"Scripts\\Blizzard.j","function helper takes nothing returns nothing\nendfunction\n"},{"war3map.j","public member must not masquerade as a map script"}});mpq(scratch/L"map.w3x",{{"Scripts\\common.j","map override must not replace builtins"},{"Scripts\\war3map.j",entries}});Archives a(scratch);require(!a.readCandidates({"war3map.j"},ArchiveScope::Map),"Map-only lookup fell back to public archive");a.mountMap(scratch/L"map.w3x");auto p=Program::read(a);require(p.types()[0].name=="sourcehandle" && p.sources()[2].name=="Scripts\\war3map.j" && p.function("config") && p.function("main"),"Builtin scope or protected-map script alias differs");require(a.readCandidates({"Scripts/common.j"},ArchiveScope::Common)==a.readCandidates({"scripts/common.j"},ArchiveScope::Common),"Builtin source cache not shared");mpq(scratch/L"root.w3x",{{"war3map.j",entries},{"Scripts\\war3map.j","not selected"}});a.mountMap(scratch/L"root.w3x");require(Program::read(a).sources()[2].name=="war3map.j","Root map script preference differs");mpq(scratch/L"missing.w3x",{{"other.txt","x"}});a.mountMap(scratch/L"missing.w3x");rejects([&]{Program::read(a);});unsigned index=0;for(auto text:{"function config takes nothing returns integer\nreturn 1\nendfunction\nfunction main takes nothing returns nothing\nendfunction\n","native config takes nothing returns nothing\nfunction main takes nothing returns nothing\nendfunction\n","function config takes nothing returns nothing\nendfunction\nfunction main takes integer value returns nothing\nendfunction\n"}){auto path=scratch/(L"entry-"+std::to_wstring(index++)+L".w3x");mpq(path,{{"war3map.j",text}});a.mountMap(path);rejects([&]{Program::read(a);});}});
    require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded into JASS tests");std::cout<<"RESULT passed="<<passed<<" failed="<<failed<<'\n';return failed?1:0;
}
